INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1uv4y1w7zf', 'course-bili-bv1uv4y1w7zf', '100001', '0', 'BILI-WRK-004', 'course-category-workplace', 'instructor-bili-383587023', '清华大学【领导力的逻辑】（全10讲）吴维库 宝藏课程', '11 讲完整课程 · 2 小时 5 分钟', '资源整理来自网络，侵权请联系删除。讲师：吴维库教授 吴维库博士，清华大学经济管理学院领导力与组织管理系教授，博士生导师。哈尔滨工业大学硕士，清华大学博士。1994 吴维库博士在清华大学经济管理学院企业管理系任教。', '课程简介：资源整理来自网络，侵权请联系删除。讲师：吴维库教授 吴维库博士，清华大学经济管理学院领导力与组织管理系教授，博士生导师。哈尔滨工业大学硕士，清华大学博士。1994 吴维库博士在清华大学经济管理学院企业管理系任教。曾在美国宾夕法尼亚大学沃顿商学院进修公司战略及领导学，在哈佛大学商学院和香港科技大学恒隆管理研究中心研修领导学与组织行为学，在领导学研究方面颇有建树。课程结构：共 2 章 11 讲，累计时长 2 小时 5 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["掌握结构化表达与高效汇报的底层方法","提升跨部门协作、向上管理与冲突处理能力","构建可迁移的职场写作与演示材料体系","完成个人职业发展规划与求职准备"]', '["入职 0-5 年希望快速成长的职场人","带团队或即将晋升管理岗的骨干","求职与转岗人群"]', '["具备真实的职场或实习经历","愿意结合自身工作场景完成练习"]', 'intermediate', 'zh-CN', 'https://i2.hdslb.com/bfs/archive/6dafbd742ddab662819544ee93f2b4e20c1bf265.jpg', '["职场技能","沟通表达","职业发展","清华大学","领导力的逻辑","全10讲"]', 7515, 11, 116119, '4.5', 52722, 'BV1uV4y1W7Zf', NULL, NULL, NULL, 1, 0, 'standard', NULL, '复利的奇迹价值投资', 0, 'tenant', 'published', '2022-08-28T12:00:00.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
