VALUES
    ('course-bili-season-42241', 'course-bili-season-42241', '100001', '0', 'BILI-WRK-016', 'course-category-workplace', 'instructor-bili-332911876', 'PPT制作教程简易版', '33 讲完整课程 · 2 小时 39 分钟', '一集就上手PPT的简易制作教程。有什么建议可评论告诉我哦。所用软件是微软office powerpoint，只要是2016以上的版本或office365都可以。打开方式：桌面找到Powerpoint图标双击打开，', '课程简介：一集就上手PPT的简易制作教程。有什么建议可评论告诉我哦。所用软件是微软office powerpoint，只要是2016以上的版本或office365都可以。打开方式：桌面找到Powerpoint图标双击打开，双击“空白演示文稿”即可进入到编辑界面。课程结构：共 1 章 33 讲，累计时长 2 小时 39 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["掌握结构化表达与高效汇报的底层方法","提升跨部门协作、向上管理与冲突处理能力","构建可迁移的职场写作与演示材料体系","完成个人职业发展规划与求职准备"]', '["入职 0-5 年希望快速成长的职场人","带团队或即将晋升管理岗的骨干","求职与转岗人群"]', '["具备真实的职场或实习经历","愿意结合自身工作场景完成练习"]', 'intermediate', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/cf3c466ceaf6680a84b9d9509018b6daf6d35590.jpg', '["职场技能","沟通表达","职业发展","PPT制作教程简易版"]', 9548, 33, 592653, '4.6', 83477, 'BV1mf4y1L7EK', NULL, NULL, NULL, 1, 0, 'standard', NULL, '呆伯特PPT', 0, 'tenant', 'published', '2021-07-08T13:51:35.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
